IREE_API_EXPORT iree_status_t iree_hal_vulkan_device_request_stop(
    iree_hal_device_t* base_device, iree_hal_semaphore_t* retired) {
  iree_hal_vulkan_logical_device_t* device =
      iree_hal_vulkan_logical_device_cast(base_device);
  iree_atomic_store(&device->external_stop_remaining,
                    (int32_t)device->queues.lane_count, iree_memory_order_release);
  iree_status_t status = iree_ok_status();
  for (iree_host_size_t i = 0; i < device->queues.lane_count; ++i) {
    iree_status_t next = iree_hal_vulkan_queue_request_stop(
        &device->queues.lanes[i], retired, &device->external_stop_remaining);
    if (iree_status_is_ok(status)) status = next;
    else iree_status_free(next);
  }
  return status;
}

