iree_status_t iree_hal_vulkan_queue_request_stop(
    iree_hal_vulkan_queue_t* queue, iree_hal_semaphore_t* retired,
    iree_atomic_int32_t* remaining) {
  iree_slim_mutex_lock(&queue->submission_mutex);
  if (queue->external_retired) {
    iree_slim_mutex_unlock(&queue->submission_mutex);
    return iree_make_status(IREE_STATUS_FAILED_PRECONDITION,
                            "external retirement already requested");
  }
  bool exited = queue->completion_thread_exited;
  if (!exited) {
    iree_hal_semaphore_retain(retired);
    queue->external_retired = retired;
    queue->external_stop_remaining = remaining;
  }
  iree_atomic_store(&queue->stop_requested, 1, iree_memory_order_release);
  iree_slim_mutex_unlock(&queue->submission_mutex);
  if (exited) {
    if (iree_atomic_fetch_sub(remaining, 1, iree_memory_order_acq_rel) == 1)
      return iree_hal_semaphore_signal(retired, 1, NULL);
    return iree_ok_status();
  }
  return iree_hal_vulkan_queue_signal_wakeup(queue);
}

